  /** 图形色。必填 */
  seriesColor: string;
}

// 引擎级通用样式键（所有物料可用）: opacity, flipX, flipY, passThrough, hoverPointer, clip, blend, filterBlur, filterBrightness, filterContrast, filterSaturate, filterHueRotate
// 颜色值可写 "theme:<slot>" 引用文档主题色板；槽位: "primary" | "text" | "textSecondary" | "background" | "accent" | "accentSecondary" | "danger" | "warning" | "info" | "success"
interface MaterialStyle {
  /** 范围 ≥ 0 且 ≤ 1 */
  opacity?: number;
  flipX?: boolean;
  flipY?: boolean;
  passThrough?: boolean;
  hoverPointer?: boolean;
  clip?: boolean;
  /** 取值: "normal" | "multiply" | "screen" | "overlay" | "darken" | "lighten" */
  blend?: "normal" | "multiply" | "screen" | "overlay" | "darken" | "lighten";
  /** 范围 ≥ 0 且 ≤ 40 */
  filterBlur?: number;
  /** 范围 ≥ 0 且 ≤ 300 */
  filterBrightness?: number;
  /** 范围 ≥ 0 且 ≤ 300 */
  filterContrast?: number;
  /** 范围 ≥ 0 且 ≤ 300 */
  filterSaturate?: number;
  /** 范围 ≥ 0 且 ≤ 360 */
  filterHueRotate?: number;
  /** 背景色。必填 */
  backgroundColor: string;
  /** 文字色。必填 */
  color: string;
  /** 网格色。必填 */
  gridColor: string;
  /** 图形色。必填 */
  seriesColor: string;
}
